24	export const UserImage: FC<Props> = ({
25	  avatarUrl,
26	  displayName,
27	  height = 32,
28	  width = 32,
29	  borderRadius = 48,
30	  onPress,
31	}) => {
32	  const [uri, setUri] = useState<string | null>(null);
33	  const textSize = () => {
34	    if (height < 20) return TextSize.xtiny;
35	    if (height < 28) return TextSize.tiny;
36	    if (height < 32) return TextSize.small;
37	    if (height < 40) return TextSize.base;
38	    if (height < 48) return TextSize.medium;
39	    if (height < 56) return TextSize.large;
40	
41	    return TextSize.xlarge;
42	  };
43	
44	  useEffect(() => {
45	    setUri(null);
46	
47	    const fetch = async () => {
48	      if (!avatarUrl) {
49	        return;
50	      }
51	
52	      try {
53	        if (await isCached(avatarUrl)) {
54	          setUri(getCachedImagePathByURL(avatarUrl));
55	          return;
56	        }
57	        const url = await fetchMedia({
58	          url: avatarUrl,
59	          width,
60	          height,
61	          serverUrl:
62	            MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
63	        });
64	        if (!url) return;
65	        await cacheImageWithKey(avatarUrl, url);
66	        setUri(getCachedImagePathByURL(avatarUrl));
67	      } catch (e) {
68	        console.log(e);
69	      }
70	    };
71	
72	    fetch();
73	  }, [avatarUrl, width, height]);
74	
75	  if (uri) {
76	    const image = (
77	      <Image
78	        source={{ uri }}
79	        width={width}
80	        height={height}
81	        style={{
82	          width,
83	          height,
84	          borderRadius,
85	          borderWidth: 2,
86	          borderColor: Colors.white20,
87	        }}
88	      />
89	    );
90	
91	    if (onPress) {
92	      return (
93	        <Button.Wrapper onPress={() => onPress(uri)}>{image}</Button.Wrapper>
94	      );
95	    }
96	
97	    return image;
98	  }
99	
100	  return (
101	    <Block
102	      width={width}
103	      height={height}
104	      border={{
105	        borderWidth: 1,
106	        borderColor: Colors.white20,
107	        borderRadius,
108	      }}
109	      background={Colors.white20}
110	      align="center"
111	      justify="center"
112	    >
113	      <Text size={textSize()} color={Colors.white50}>
114	        {displayName?.charAt(0).toUpperCase()}
115	      </Text>
116	    </Block>
117	  );
118	};
